import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2021-05-06","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-05-06","date":"2021-05-06T00:00:00.000Z","updated":"2021-05-07T00:00:00.000Z","tags":["Ceph","性能优化","缓存策略","Intel合作","代码审查"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-05-06.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-05-06.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Performance_Meeting_2021-05-06.md"};function r(n,l,s,h,p,u){return i(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph性能会议主要讨论了Ceph存储系统在性能优化、缓存策略以及与Intel合作等方面的问题。与会者分享了在实际操作中遇到的问题和解决方案，并对未来的工作方向进行了探讨。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph性能问题</strong>：</p><ul><li>讨论了在OpenShift环境下Ceph的性能问题，特别是与IBM Cloud Packs的集成问题。</li><li>提到了在RBD设备上运行XCD的复杂用例，以及Gluster和Ceph的集成问题。</li></ul></li><li><p><strong>缓存策略</strong>：</p><ul><li>讨论了缓存层的选择，包括Intel的OpenCAS和LVM缓存。</li><li>探讨了直接IO（Direct IO）和缓冲IO（Buffered IO）的使用场景和性能影响。</li></ul></li><li><p><strong>与Intel的合作</strong>：</p><ul><li>讨论了Intel的OpenCAS项目，以及如何在客户端侧进行本地缓存以提高性能。</li><li>探讨了与Intel合作的可能性，以优化Ceph的性能。</li></ul></li><li><p><strong>代码审查和开发</strong>：</p><ul><li>讨论了多个Pull Request（PR），包括对缓冲IO的处理、C-Store的初始支持等。</li><li>提到了对OMap性能的测试和优化，以及对RocksDB缓存行为的深入分析。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ol><li><p><strong>缓存策略的优化</strong>：</p><ul><li>决定进一步测试和优化缓存策略，特别是直接IO和缓冲IO的使用。</li><li>计划与Intel合作，探索使用OpenCAS作为客户端缓存解决方案。</li></ul></li><li><p><strong>代码审查和开发</strong>：</p><ul><li>对多个PR进行了讨论，包括对缓冲IO的处理和C-Store的支持。</li><li>决定继续深入分析RocksDB的缓存行为，以优化OMap性能。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><p><strong>性能测试</strong>：</p><ul><li>继续进行性能测试，特别是对缓存策略的优化。</li><li>与Intel合作，进行OpenCAS的性能测试和集成。</li></ul></li><li><p><strong>代码开发和审查</strong>：</p><ul><li>继续审查和优化相关的Pull Request。</li><li>深入分析RocksDB的缓存行为，以解决OMap性能问题。</li></ul></li><li><p><strong>合作与交流</strong>：</p><ul><li>与Intel保持沟通，探讨进一步的合作可能性。</li><li>定期进行技术交流和问题讨论，以确保项目的顺利进行。</li></ul></li></ol><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>Randy</li><li>Michael Kidd</li><li>Joe Quinn</li><li>Adam</li><li>Gabby</li><li>其他核心开发人员</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论了所有议题后结束，与会者同意继续进行相关的测试和开发工作，并保持与Intel的合作沟通。下次会议将继续讨论相关进展和问题。</p><h4 id="改进说明" tabindex="-1">改进说明 <a class="header-anchor" href="#改进说明" aria-label="Permalink to &quot;改进说明&quot;">​</a></h4><ol><li>在会议概述中，增加了对会议主要议题的简要描述。</li><li>在主要议题中，详细列出了每个议题的具体讨论内容。</li><li>在决定事项中，明确了具体决定和后续行动计划。</li><li>在参会人员中，列出了主要的参会者。</li><li>在会议结束部分，总结了会议的成果和后续计划。</li></ol><h4 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h4><ol><li>原始字幕内容中有些关键词可能有误，因此在总结中尽量使用了计算机科学/ceph相关领域的英文原文关键词。</li><li>由于原始字幕内容有限，可能存在一些遗漏或误解的重要信息。</li></ol>',17)])])}const _=e(o,[["render",r]]);export{c as __pageData,_ as default};
